import { CookieService } from 'ngy-cookie'
import { WindowRefService } from '../Services/window-ref.service'
import { ActivatedRoute, Router, RouterLink } from '@angular/router'
import { Component, type OnInit, inject, signal, ChangeDetectionStrategy } from '@angular/core'
import { FormsModule } from '@angular/forms'
import { FormField, form, minLength, required, submit } from '@angular/forms/signals'
import { library } from '@fortawesome/fontawesome-svg-core'
import { UserService } from '../Services/user.service'
import { faEye, faEyeSlash, faKey } from '@fortawesome/free-solid-svg-icons'
import { faGoogle } from '@fortawesome/free-brands-svg-icons'
import { ConfigurationService } from '../Services/configuration.service'
import { BasketService } from '../Services/basket.service'
import { PasskeyService } from '../Services/passkey.service'
import { MatCheckbox } from '@angular/material/checkbox'
import { MatIconModule } from '@angular/material/icon'
import { MatTooltip } from '@angular/material/tooltip'
import { MatIconButton, MatButtonModule } from '@angular/material/button'
import { MatInputModule } from '@angular/material/input'
import { TranslateModule, TranslateService } from '@ngx-translate/core'
import { HttpErrorResponse } from '@angular/common/http'
import { MatFormFieldModule, MatLabel, MatError, MatSuffix } from '@angular/material/form-field'
import { firstValueFrom, of } from 'rxjs'
import { catchError } from 'rxjs/operators'

import { MatCardModule } from '@angular/material/card'

library.add(faKey, faEye, faEyeSlash, faGoogle)

const oauthProviderUrl = 'https://accounts.google.com/o/oauth2/v2/auth'

@Component({
  changeDetection: ChangeDetectionStrategy.Eager,
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss'],
  imports: [MatCardModule, MatFormFieldModule, MatLabel, TranslateModule, MatInputModule, FormsModule, FormField, MatError, MatIconButton, MatSuffix, MatTooltip, RouterLink, MatButtonModule, MatIconModule, MatCheckbox]
})

export class LoginComponent implements OnInit {
  private readonly configurationService = inject(ConfigurationService)
  private readonly userService = inject(UserService)
  private readonly windowRefService = inject(WindowRefService)
  private readonly cookieService = inject(CookieService)
  private readonly router = inject(Router)
  private readonly route = inject(ActivatedRoute)
  private readonly basketService = inject(BasketService)
  private readonly passkeyService = inject(PasskeyService)
  private readonly translate = inject(TranslateService)

  public readonly loginModel = signal({
    email: '',
    password: '',
    rememberMe: false
  })

  public readonly loginForm = form(this.loginModel, (s) => {
    required(s.email)
    required(s.password)
    minLength(s.password, 1)
  })

  public hide = true
  public error = signal<any>(null)
  public clientId = '1005568560502-6hm16lef8oh46hr2d98vf2ohlnj4nfhq.apps.googleusercontent.com'
  public oauthUnavailable = true
  public redirectUri = ''
  public testingUsername = 'testing@juice-sh.op'
  public testingPassword = 'IamUsedForTesting'

  ngOnInit (): void {
    const email = localStorage.getItem('email')
    this.loginModel.update((model) => ({ ...model, rememberMe: !!email }))

    this.redirectUri = `${this.windowRefService.nativeWindow.location.protocol}//${this.windowRefService.nativeWindow.location.host}`
    this.configurationService.getApplicationConfiguration().subscribe({
      next: (config) => {
        if (config?.application?.googleOauth) {
          this.clientId = config.application.googleOauth.clientId
          const authorizedRedirect = config.application.googleOauth.authorizedRedirects.find(r => r.uri === this.redirectUri)
          if (authorizedRedirect) {
            this.oauthUnavailable = false
            this.redirectUri = authorizedRedirect.proxy ? authorizedRedirect.proxy : authorizedRedirect.uri
          } else {
            this.oauthUnavailable = true
            console.log(this.redirectUri + ' is not an authorized redirect URI for this application.')
          }
        }
      },
      error: (err) => { console.log(err) }
    })
  }

  login () {
    return submit(this.loginForm, async () => {
      const user = {
        email: this.loginModel().email,
        password: this.loginModel().password
      }

      if (this.loginModel().rememberMe) {
        localStorage.setItem('email', user.email)
      } else {
        localStorage.removeItem('email')
      }

      try {
        const authentication: any = await firstValueFrom(this.userService.login(user))
        const redirectUrl = this.route.snapshot.queryParamMap.get('redirectUrl') ?? '/search'
        await this.handleAuthentication(authentication, redirectUrl)
      } catch (err: any) {
        const error = err?.error
        if (error?.status && error?.data && error.status === 'totp_token_required') {
          localStorage.setItem('totp_tmp_token', error.data.tmpToken)
          await this.router.navigate(['/2fa/enter'])
          return
        }
        localStorage.removeItem('token')
        this.cookieService.remove('token')
        sessionStorage.removeItem('bid')
        this.error.set(error)
        this.userService.isLoggedIn.next(false)
        this.loginForm.email().reset()
        this.loginForm.password().reset()
      }
    })
  }

  async passkeyLogin () {
    try {
      const { options, authToken } = await firstValueFrom(this.passkeyService.loginOptions(this.loginModel().email || undefined))
      const assertion = await this.passkeyService.createAssertion(options)
      const authentication = await firstValueFrom(this.passkeyService.loginVerify(assertion, authToken))
      const redirectUrl = this.route.snapshot.queryParamMap.get('redirectUrl') ?? '/search'
      await this.handleAuthentication(authentication, redirectUrl)
    } catch (err: any) {
      if (err instanceof HttpErrorResponse) {
        this.error.set(typeof err.error === 'string' && err.error ? err.error : this.translate.instant('PASSKEY_LOGIN_FAILED'))
      } else {
        this.error.set(err?.message || this.translate.instant('PASSKEY_LOGIN_FAILED'))
      }
    }
  }

  private async handleAuthentication (authentication: any, redirectUrl: string) {
    localStorage.setItem('token', authentication.token)
    const expires = new Date()
    expires.setHours(expires.getHours() + 8)
    this.cookieService.put('token', authentication.token, { expires })
    sessionStorage.setItem('bid', authentication.bid)

    await firstValueFrom(this.basketService.mergeGuestBasketIntoUserBasket(authentication.bid)
      .pipe(
        catchError((err) => {
          console.log(err)
          return of(void 0)
        })
      ))
    await this.completeLogin(redirectUrl)
  }

  private completeLogin (redirectUrl: string): Promise<boolean> {
    this.basketService.updateNumberOfCartItems()
    this.userService.isLoggedIn.next(true)
    return this.router.navigateByUrl(redirectUrl)
  }

  googleLogin () {
    this.windowRefService.nativeWindow.location.replace(`${oauthProviderUrl}?client_id=${this.clientId}&response_type=token&scope=email&redirect_uri=${this.redirectUri}`)
  }
}
